```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::notifier;

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        // Authority: Notifier<'digest'> only. Announce the digest on the one
        // channel this node holds, then report publication.
        let message = format!("{}: {}", composed.date, composed.overview);
        let _accepted = notifier::notify(&message);

        // ensures present(published)
        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published: true,
        }
    }
}

export!(Node);
